    Assertions.assertEquals("CANCEL LOAD FROM default_cluster:testDb WHERE `label` LIKE 'doris_test_label'", stmt.toString());
    CompoundPredicate compoundAndPredicate = new CompoundPredicate(Operator.AND, labelBinaryPredicate, stateBinaryPredicate);
    stmt = new CancelLoadStmt(null, compoundAndPredicate);
    stmt.analyze(analyzer);
    Assertions.assertEquals("CANCEL LOAD FROM default_cluster:testDb WHERE `label` = 'doris_test_label' AND `state` = 'LOADING'", stmt.toString());
    CompoundPredicate compoundOrPredicate = new CompoundPredicate(Operator.OR, labelBinaryPredicate, stateBinaryPredicate);
    stmt = new CancelLoadStmt(null, compoundOrPredicate);
    stmt.analyze(analyzer);
    Assertions.assertEquals("CANCEL LOAD FROM default_cluster:testDb WHERE `label` = 'doris_test_label' OR `state` = 'LOADING'", stmt.toString());
    // test match
    List<LoadJob> loadJobs = new ArrayList<>();
    Database db = Env.getCurrentInternalCatalog().getDbOrMetaException("default_cluster:testDb");
    long dbId = db.getId();
    Table tbl = db.getTableNullable(tblName);
    long tblId = tbl.getId();
    InsertLoadJob insertLoadJob1 = new InsertLoadJob("doris_test_label", 1L, dbId, tblId, 0, "", "");
    loadJobs.add(insertLoadJob1);
    InsertLoadJob insertLoadJob2 = new InsertLoadJob("doris_test_label_1", 2L, dbId, tblId, 0, "", "");
    loadJobs.add(insertLoadJob2);
    InsertLoadJob insertLoadJob3 = new InsertLoadJob("doris_test_label_2", 3L, dbId, tblId, 0, "", "");
    loadJobs.add(insertLoadJob3);
    // label
    stmt = new CancelLoadStmt(null, labelBinaryPredicate);
    stmt.analyze(analyzer);
    List<LoadJob> matchLoadJobs = new ArrayList<>();
    LoadManager.addNeedCancelLoadJob(stmt, loadJobs, matchLoadJobs);
    Assertions.assertEquals(1, matchLoadJobs.size());
    // state
    matchLoadJobs.clear();
    stmt = new CancelLoadStmt(null, stateBinaryPredicate);
    stmt.analyze(analyzer);
    LoadManager.addNeedCancelLoadJob(stmt, loadJobs, matchLoadJobs);
    Assertions.assertEquals(0, matchLoadJobs.size());
    // or
    matchLoadJobs.clear();
    stmt = new CancelLoadStmt(null, compoundOrPredicate);
    stmt.analyze(analyzer);
    LoadManager.addNeedCancelLoadJob(stmt, loadJobs, matchLoadJobs);
    Assertions.assertEquals(1, matchLoadJobs.size());
    // and
    matchLoadJobs.clear();
    stmt = new CancelLoadStmt(null, compoundAndPredicate);
    stmt.analyze(analyzer);
    LoadManager.addNeedCancelLoadJob(stmt, loadJobs, matchLoadJobs);
    Assertions.assertEquals(0, matchLoadJobs.size());
}

