@Test
public void testQuerySchema() throws Exception {
    connectContext.setDatabase("default_cluster:test");
    String create1 = "create table test.qs1 (k1 int, k2 int) distributed by hash(k1) " + "buckets 1 properties('replication_num' = '1')";
    String create2 = "create table test.qs2 (k1 int, k2 int) distributed by hash(k1) " + "buckets 1 properties('replication_num' = '1')";
    createTables(create1, create2);
    String view1 = "create view test.v1 as select qs1.k1 from qs1 join qs2 on qs1.k1 = qs2.k1";
    String view2 = "create view test.v2 as with cte(s1) as (select * from v1) select * from cte";
    createView(view1);
    createView(view2);
    String sql1 = "select * from v1";
    org.apache.doris.analysis.SqlParser parser = new org.apache.doris.analysis.SqlParser(new org.apache.doris.analysis.SqlScanner(new StringReader(sql1)));
    QueryStmt stmt = (QueryStmt) SqlParserUtils.getStmt(parser, 0);
    Map<Long, TableIf> tableMap = Maps.newHashMap();
    Set<String> parentViewNameSet = Sets.newHashSet();
    Analyzer analyzer = new Analyzer(Env.getCurrentEnv(), ConnectContext.get());
    stmt.getTables(analyzer, true, tableMap, parentViewNameSet);
    List<String> createStmts = Lists.newArrayList();
    for (TableIf tbl : tableMap.values()) {
        List<String> createTableStmts = Lists.newArrayList();
        Env.getDdlStmt(tbl, createTableStmts, null, null, false, true, -1L);
        createStmts.add(createTableStmts.get(0));
        if (tbl.getName().equals("qs1")) {
            Assert.assertEquals("CREATE TABLE `qs1` (\n" + "  `k1` int(11) NULL,\n" + "  `k2` int(11) NULL\n" + ") ENGINE=OLAP\n" + "DUPLICATE KEY(`k1`, `k2`)\n" + "COMMENT 'OLAP'\n" + "DISTRIBUTED BY HASH(`k1`) BUCKETS 1\n" + "PROPERTIES (\n" + "\"replication_allocation\" = \"tag.location.default: 1\",\n" + "\"in_memory\" = \"false\",\n" + "\"storage_format\" = \"V2\",\n" + "\"light_schema_change\" = \"true\",\n" + "\"disable_auto_compaction\" = \"false\"\n" + ");", createTableStmts.get(0));
        } else {
            Assert.assertEquals("CREATE TABLE `qs2` (\n" + "  `k1` int(11) NULL,\n" + "  `k2` int(11) NULL\n" + ") ENGINE=OLAP\n" + "DUPLICATE KEY(`k1`, `k2`)\n" + "COMMENT 'OLAP'\n" + "DISTRIBUTED BY HASH(`k1`) BUCKETS 1\n" + "PROPERTIES (\n" + "\"replication_allocation\" = \"tag.location.default: 1\",\n" + "\"in_memory\" = \"false\",\n" + "\"storage_format\" = \"V2\",\n" + "\"light_schema_change\" = \"true\",\n" + "\"disable_auto_compaction\" = \"false\"\n" + ");", createTableStmts.get(0));
        }
    }
    Assert.assertEquals(2, createStmts.size());
}

