        Assert.assertEquals(PrimitiveType.DECIMALV2, type.getType().getPrimitiveType());
    }
    Assert.assertEquals(12, ((ScalarType) type.getType()).getScalarPrecision());
    Assert.assertEquals(5, ((ScalarType) type.getType()).getScalarScale());
