@ParameterizedTest
@ValueSource(strings = { "AGGREGATE", "UNIQUE", "DUPLICATE" })
public void testCreateWithPartition(String keyType) throws Exception {
    String aggregation = keyType.equals("AGGREGATE") ? "SUM" : "";
    createTable("CREATE TABLE test.t1 (" + "  pk INT NOT NULL," + "  v1 INT " + aggregation + ") " + keyType + " KEY (pk)" + "PARTITION BY RANGE(pk) (" + "  PARTITION p1 VALUES LESS THAN ('10')," + "  PARTITION p2 VALUES LESS THAN ('20')" + ")" + "DISTRIBUTED BY HASH(pk) BUCKETS 1 PROPERTIES ('replication_num' = '1')");
    createTable("CREATE TABLE test.t2 (" + "  pk INT NOT NULL," + "  v2 INT " + aggregation + ") " + keyType + " KEY (pk)" + "PARTITION BY LIST(pk) (" + "  PARTITION odd VALUES IN ('10', '30', '50', '70', '90')," + "  PARTITION even VALUES IN ('20', '40', '60', '80')" + ")" + "DISTRIBUTED BY HASH(pk) BUCKETS 1 PROPERTIES ('replication_num' = '1')");
    new StmtExecutor(connectContext, "CREATE MATERIALIZED VIEW mv " + "BUILD IMMEDIATE REFRESH COMPLETE KEY (pk) " + "PARTITION BY (t1.pk)" + "DISTRIBUTED BY HASH(pk) " + "PROPERTIES ('replication_num' = '1') " + "AS SELECT t1.pk, v1, v2 FROM test.t1, test.t2 WHERE test.t1.pk = test.t2.pk").execute();
    Assertions.assertNull(connectContext.getState().getErrorCode(), connectContext.getState().getErrorMessage());
    connectContext.getEnv().dropMaterializedView((DropMaterializedViewStmt) parseAndAnalyzeStmt("DROP MATERIALIZED VIEW mv"));
    new StmtExecutor(connectContext, "CREATE MATERIALIZED VIEW mv " + "BUILD IMMEDIATE REFRESH COMPLETE KEY (pk) " + "PARTITION BY (t2.pk)" + "DISTRIBUTED BY HASH(pk) " + "PROPERTIES ('replication_num' = '1') " + "AS SELECT t2.pk, v1, v2 FROM test.t1, test.t2 WHERE test.t1.pk = test.t2.pk").execute();
    Assertions.assertNull(connectContext.getState().getErrorCode(), connectContext.getState().getErrorMessage());
    connectContext.getEnv().dropMaterializedView((DropMaterializedViewStmt) parseAndAnalyzeStmt("DROP MATERIALIZED VIEW mv"));
    connectContext.getState().reset();
    new StmtExecutor(connectContext, "CREATE MATERIALIZED VIEW mv " + "BUILD IMMEDIATE REFRESH COMPLETE KEY (pk) " + "PARTITION BY (t1.pk)" + "DISTRIBUTED BY HASH(pk) " + "PROPERTIES ('replication_num' = '1') " + "AS SELECT t2.pk, v1, v2 FROM test.t1, test.t2 WHERE test.t1.pk = test.t2.pk").execute();
    Assertions.assertTrue(connectContext.getState().getErrorMessage().contains("Failed to map the partition column name"));
    connectContext.getState().reset();
    new StmtExecutor(connectContext, "CREATE MATERIALIZED VIEW mv " + "BUILD IMMEDIATE REFRESH COMPLETE KEY (pk) " + "PARTITION BY (v1)" + "DISTRIBUTED BY HASH(pk) " + "PROPERTIES ('replication_num' = '1') " + "AS SELECT t2.pk, v1, v2 FROM test.t1, test.t2 WHERE test.t1.pk = test.t2.pk").execute();
    Assertions.assertTrue(connectContext.getState().getErrorMessage().contains("The partition columns doesn't match the ones in base table"));
}

