    ExceptionChecker.expectThrowsWithMsg(AlterCancelException.class, "errCode = 2, detailMessage = unknown table, tableName=test", () -> table.writeLockOrAlterCancelException());
    ExceptionChecker.expectThrowsWithMsg(MetaNotFoundException.class, "errCode = 7, detailMessage = unknown table, tableName=test", () -> table.tryWriteLockOrMetaException(1000, TimeUnit.MILLISECONDS));
