    try {
        env.getCatalogMgr().showCatalogs((ShowCatalogStmt) parseAndAnalyzeStmt("show catalog iceberg;", user2Ctx));
        Assert.fail("");
    } catch (AnalysisException e) {
        Assert.assertEquals(e.getMessage(), "errCode = 2, detailMessage = Access denied for user 'default_cluster:user2' to catalog 'iceberg'");
    }
    //test show create catalog: have permission to hive, have no permission to iceberg;
    ShowCreateCatalogStmt user2ShowCreateHive = (ShowCreateCatalogStmt) parseAndAnalyzeStmt("show create catalog hive;", user2Ctx);
    List<List<String>> user2ShowCreateHiveResult = env.getCatalogMgr().showCreateCatalog(user2ShowCreateHive).getResultRows();
    Assert.assertTrue(user2ShowCreateHiveResult.stream().map(l -> l.get(0)).anyMatch(c -> c.equals("hive")));
    try {
        env.getCatalogMgr().showCreateCatalog((ShowCreateCatalogStmt) parseAndAnalyzeStmt("show create catalog iceberg;", user2Ctx));
        Assert.fail("");
    } catch (AnalysisException e) {
        Assert.assertEquals(e.getMessage(), "errCode = 2, detailMessage = Access denied for user 'default_cluster:user2' to catalog 'iceberg'");
    }
}

