        {
            ctx.getCurrentUserIdentity();
            minTimes = 1;
            result = opUser;
        }
    };
    Assert.assertFalse(auth.checkGlobalPriv(ctx, PrivPredicate.OPERATOR));
    grantStmt = new GrantStmt(opUser, null, new TablePattern("*", "*", "*"), privileges);
