/*
     * A -> B(A): will run into dead loop, so we detect it and throw exception.
     *
     *  UnboundRelation(student)               limit(1)                          limit(1)
     *                              ->           |                   ->             |                 ->    ...
     *                                    UnboundRelation(student)          UnboundRelation(student)
     *
     * you should split A into some states:
     * 1. A(not rewrite)
     * 2. A'(already rewrite)
     *
     * then make sure the A' is new object and not equals to A (overwrite equals method and compare the states),
     * so the case change to 'A -> B(C)', because C has different state with A。
     *
     * the similar case is: A -> B(C(A))
     */
@Test
public void a2ba() {
    // invalid case
    Assertions.assertThrows(IllegalStateException.class, () -> {
        UnboundRelation student = new UnboundRelation(RelationUtil.newRelationId(), ImmutableList.of("student"));
        LogicalLimit<UnboundRelation> limit = new LogicalLimit<>(1, 0, student);
        PlanChecker.from(connectContext, student).applyBottomUp(unboundRelation().then(limit::withChildren)).checkGroupNum(2).matchesFromRoot(logicalLimit(logicalOlapScan().when(student::equals)).when(limit::equals));
    });
    // use relation id to divide different unbound relation.
    UnboundRelation a = new UnboundRelation(RelationUtil.newRelationId(), ImmutableList.of("student"));
    UnboundRelation a2 = new UnboundRelation(RelationUtil.newRelationId(), ImmutableList.of("student"));
    LogicalLimit<UnboundRelation> limit = new LogicalLimit<>(1, 0, a2);
    PlanChecker.from(connectContext, a).setMaxInvokeTimesPerRule(1000).applyBottomUp(unboundRelation().when(unboundRelation -> unboundRelation.getId().equals(a.getId())).then(unboundRelation -> limit.withChildren(new UnboundRelation(a2.getId(), unboundRelation.getNameParts())))).checkGroupNum(2).matchesFromRoot(logicalLimit(unboundRelation().when(a2::equals)).when(limit::equals));
}

