@Test
public void testRecomputeLogicalProperties() {
    UnboundRelation unboundTable = new UnboundRelation(RelationUtil.newRelationId(), ImmutableList.of("score"));
    LogicalLimit<UnboundRelation> unboundLimit = new LogicalLimit<>(1, 0, unboundTable);
    LogicalOlapScan boundTable = new LogicalOlapScan(RelationUtil.newRelationId(), PlanConstructor.score);
    LogicalLimit<Plan> boundLimit = unboundLimit.withChildren(ImmutableList.of(boundTable));
    PlanChecker.from(connectContext, unboundLimit).checkMemo(memo -> {
        LogicalProperties logicalProperties = memo.getRoot().getLogicalProperties();
        Assertions.assertTrue(logicalProperties instanceof UnboundLogicalProperties);
    }).applyBottomUp(unboundRelation().then(unboundRelation -> boundTable)).applyBottomUp(logicalPlan().when(plan -> plan.canBind() && !(plan instanceof LeafPlan)).then(LogicalPlan::recomputeLogicalProperties)).checkGroupNum(2).checkMemo(memo -> {
        LogicalProperties logicalProperties = memo.getRoot().getLogicalProperties();
        Assertions.assertEquals(boundTable.getLogicalProperties().getOutput(), logicalProperties.getOutput());
    }).matchesFromRoot(logicalLimit(logicalOlapScan().when(boundTable::equals)).when(boundLimit::equals));
}

