@Test
public void test() {
    PlanChecker.from(MemoTestUtils.createConnectContext()).analyze(new LogicalLimit<>(10, 0, new LogicalJoin<>(JoinType.LEFT_OUTER_JOIN, ImmutableList.of(new EqualTo(new UnboundSlot("sid"), new UnboundSlot("id"))), new LogicalOlapScan(RelationUtil.newRelationId(), PlanConstructor.score), new LogicalOlapScan(RelationUtil.newRelationId(), PlanConstructor.student)))).applyTopDown(logicalLimit(logicalJoin()).then(limit -> {
        LogicalJoin<GroupPlan, GroupPlan> join = limit.child();
        switch(join.getJoinType()) {
            case LEFT_OUTER_JOIN:
                return join.withChildren(limit.withChildren(join.left()), join.right());
            case RIGHT_OUTER_JOIN:
                return join.withChildren(join.left(), limit.withChildren(join.right()));
            case CROSS_JOIN:
                return join.withChildren(limit.withChildren(join.left()), limit.withChildren(join.right()));
            case INNER_JOIN:
                if (!join.getHashJoinConjuncts().isEmpty()) {
                    return join.withChildren(limit.withChildren(join.left()), limit.withChildren(join.right()));
                } else {
                    return limit;
                }
            case LEFT_ANTI_JOIN:
            // todo: support anti join.
            default:
                return limit;
        }
    })).matchesFromRoot(logicalJoin(logicalLimit(logicalOlapScan()), logicalOlapScan()));
}

/**
 * Original:
 * Project(name)
 * |---Project(name)
 *     |---UnboundRelation
 *
 * After rewrite:
 * Project(name)
 * |---Project(rewrite)
 *     |---Project(rewrite_inside)
 *         |---UnboundRelation
 */
@Test
public void testRewriteMiddlePlans() {
    UnboundRelation unboundRelation = new UnboundRelation(RelationUtil.newRelationId(), Lists.newArrayList("test"));
    LogicalProject insideProject = new LogicalProject<>(ImmutableList.of(new SlotReference("name", StringType.INSTANCE, true, ImmutableList.of("test"))), unboundRelation);
    LogicalProject rootProject = new LogicalProject<>(ImmutableList.of(new SlotReference("name", StringType.INSTANCE, true, ImmutableList.of("test"))), insideProject);
    // Project -> Project -> Relation
    Memo memo = new Memo(rootProject);
    Group leafGroup = memo.getGroups().stream().filter(g -> g.getGroupId().asInt() == 0).findFirst().get();
    Group targetGroup = memo.getGroups().stream().filter(g -> g.getGroupId().asInt() == 1).findFirst().get();
    LogicalProject rewriteInsideProject = new LogicalProject<>(ImmutableList.of(new SlotReference("rewrite_inside", StringType.INSTANCE, false, ImmutableList.of("test"))), new GroupPlan(leafGroup));
    LogicalProject rewriteProject = new LogicalProject<>(ImmutableList.of(new SlotReference("rewrite", StringType.INSTANCE, true, ImmutableList.of("test"))), rewriteInsideProject);
    memo.copyIn(rewriteProject, targetGroup, true);
    Assertions.assertEquals(4, memo.getGroups().size());
    Plan node = memo.copyOut();
    Assertions.assertTrue(node instanceof LogicalProject);
    Assertions.assertEquals("name", ((LogicalProject<?>) node).getProjects().get(0).getName());
    node = node.child(0);
    Assertions.assertTrue(node instanceof LogicalProject);
    Assertions.assertEquals("rewrite", ((LogicalProject<?>) node).getProjects().get(0).getName());
    node = node.child(0);
    Assertions.assertTrue(node instanceof LogicalProject);
    Assertions.assertEquals("rewrite_inside", ((LogicalProject<?>) node).getProjects().get(0).getName());
    node = node.child(0);
    Assertions.assertTrue(node instanceof UnboundRelation);
    Assertions.assertEquals("test", ((UnboundRelation) node).getTableName());
}

/**
 * Test rewrite current Plan with its child.
 *
 * Original(Group 2 is root):
 * Group2: Project(outside)
 * Group1: |---Project(inside)
 * Group0:     |---UnboundRelation
 *
 * and we want to rewrite group 2 by Project(inside, GroupPlan(group 0))
 *
 * After rewriting we should get(Group 2 is root):
 * Group2: Project(inside)
 * Group0: |---UnboundRelation
 */
@Test
public void testEliminateRootWithChildPlanThreeLevels() {
    UnboundRelation unboundRelation = new UnboundRelation(RelationUtil.newRelationId(), Lists.newArrayList("test"));
    LogicalProject<UnboundRelation> insideProject = new LogicalProject<>(ImmutableList.of(new SlotReference("inside", StringType.INSTANCE, true, ImmutableList.of("test"))), unboundRelation);
    LogicalProject<LogicalProject<UnboundRelation>> rootProject = new LogicalProject<>(ImmutableList.of(new SlotReference("outside", StringType.INSTANCE, true, ImmutableList.of("test"))), insideProject);
    // Project -> Project -> Relation
    Memo memo = new Memo(rootProject);
    Group leafGroup = memo.getGroups().stream().filter(g -> g.getGroupId().asInt() == 0).findFirst().get();
    Group targetGroup = memo.getGroups().stream().filter(g -> g.getGroupId().asInt() == 2).findFirst().get();
    LogicalPlan rewriteProject = insideProject.withChildren(Lists.newArrayList(new GroupPlan(leafGroup)));
    memo.copyIn(rewriteProject, targetGroup, true);
    Assertions.assertEquals(2, memo.getGroups().size());
    Plan node = memo.copyOut();
    Assertions.assertTrue(node instanceof LogicalProject);
    Assertions.assertEquals(insideProject.getProjects().get(0), ((LogicalProject<?>) node).getProjects().get(0));
    node = node.child(0);
    Assertions.assertTrue(node instanceof UnboundRelation);
    Assertions.assertEquals("test", ((UnboundRelation) node).getTableName());
    // check Group 1's GroupExpression is not in GroupExpressionMaps anymore
    GroupExpression groupExpression = new GroupExpression(rewriteProject, Lists.newArrayList(leafGroup));
    Assertions.assertEquals(2, memo.getGroupExpressions().get(groupExpression).getOwnerGroup().getGroupId().asInt());
}

