@Test
public void testSimplifyCastRule() {
    executor = new ExpressionRuleExecutor(ImmutableList.of(SimplifyCastRule.INSTANCE));
    // deduplicate
    assertRewrite("CAST(1 AS tinyint)", "1");
    assertRewrite("CAST('str' AS varchar)", "'str'");
    assertRewrite("CAST(CAST(1 AS tinyint) AS tinyint)", "1");
    // deduplicate inside
    assertRewrite("CAST(CAST('str' AS varchar) AS double)", "CAST('str' AS double)");
    assertRewrite("CAST(CAST(1 AS tinyint) AS double)", "CAST(1 AS double)");
    // string literal
    assertRewrite(new Cast(new CharLiteral("123", 3), VarcharType.createVarcharType(10)), new VarcharLiteral("123", 10));
    assertRewrite(new Cast(new VarcharLiteral("123", 3), VarcharType.createVarcharType(10)), new VarcharLiteral("123", 10));
    assertRewrite(new Cast(new CharLiteral("123", 3), StringType.INSTANCE), new StringLiteral("123"));
    assertRewrite(new Cast(new VarcharLiteral("123", 3), StringType.INSTANCE), new StringLiteral("123"));
    // decimal literal
    assertRewrite(new Cast(new TinyIntLiteral((byte) 1), DecimalV2Type.createDecimalV2Type(15, 9)), new DecimalLiteral(new BigDecimal(1)));
    assertRewrite(new Cast(new SmallIntLiteral((short) 1), DecimalV2Type.createDecimalV2Type(15, 9)), new DecimalLiteral(new BigDecimal(1)));
    assertRewrite(new Cast(new IntegerLiteral(1), DecimalV2Type.createDecimalV2Type(15, 9)), new DecimalLiteral(new BigDecimal(1)));
    assertRewrite(new Cast(new BigIntLiteral(1L), DecimalV2Type.createDecimalV2Type(15, 9)), new DecimalLiteral(new BigDecimal(1)));
}

@Test
public void testSimplifyComparisonPredicateRule() {
    executor = new ExpressionRuleExecutor(ImmutableList.of(SimplifyComparisonPredicate.INSTANCE));
    Expression dtv2 = new DateTimeV2Literal(1, 1, 1, 1, 1, 1);
    Expression dt = new DateTimeLiteral(1, 1, 1, 1, 1, 1);
    Expression dtNoTime = new DateTimeLiteral(1, 1, 1, 0, 0, 0);
    Expression dv2 = new DateV2Literal(1, 1, 1);
    Expression dv2PlusOne = new DateV2Literal(1, 1, 2);
    Expression d = new DateLiteral(1, 1, 1);
    //Expression dPlusOne = new DateLiteral(1, 1, 2);
    // DateTimeV2 -> DateTime
    assertRewrite(new GreaterThan(new Cast(dt, DateTimeV2Type.SYSTEM_DEFAULT), dtv2), new GreaterThan(dt, dt));
    // DateTimeV2 -> DateV2
    assertRewrite(new GreaterThan(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2), new GreaterThan(dv2, dv2));
    assertRewrite(new LessThan(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2), new LessThan(dv2, dv2PlusOne));
    assertRewrite(new EqualTo(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2), new EqualTo(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2));
    // DateTime -> DateV2
    assertRewrite(new GreaterThan(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dt), new GreaterThan(dv2, dv2));
    assertRewrite(new LessThan(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dt), new LessThan(dv2, dv2PlusOne));
    assertRewrite(new EqualTo(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dt), new EqualTo(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dt));
    // DateTimeV2 -> Date
    assertRewrite(new GreaterThan(new Cast(d, DateTimeV2Type.SYSTEM_DEFAULT), dtv2), new GreaterThan(new Cast(d, DateTimeType.INSTANCE), dt));
    assertRewrite(new LessThan(new Cast(d, DateTimeV2Type.SYSTEM_DEFAULT), dtv2), new LessThan(new Cast(d, DateTimeType.INSTANCE), dt));
    assertRewrite(new EqualTo(new Cast(d, DateTimeV2Type.SYSTEM_DEFAULT), dtv2), new EqualTo(new Cast(d, DateTimeV2Type.SYSTEM_DEFAULT), dtv2));
    // DateTime -> Date
    assertRewrite(new GreaterThan(new Cast(d, DateTimeV2Type.SYSTEM_DEFAULT), dt), new GreaterThan(new Cast(d, DateTimeType.INSTANCE), dt));
    assertRewrite(new LessThan(new Cast(d, DateTimeV2Type.SYSTEM_DEFAULT), dt), new LessThan(new Cast(d, DateTimeType.INSTANCE), dt));
    assertRewrite(new EqualTo(new Cast(d, DateTimeV2Type.SYSTEM_DEFAULT), dt), new EqualTo(new Cast(d, DateTimeV2Type.SYSTEM_DEFAULT), dt));
    // DateV2 -> Date
    assertRewrite(new GreaterThan(new Cast(d, DateTimeV2Type.SYSTEM_DEFAULT), dv2), new GreaterThan(new Cast(d, DateTimeType.INSTANCE), dtNoTime));
    // test hour, minute and second all zero
    Expression dtv2AtZeroClock = new DateTimeV2Literal(1, 1, 1, 0, 0, 0);
    assertRewrite(new GreaterThan(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2AtZeroClock), new GreaterThan(dv2, dv2));
    assertRewrite(new LessThan(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2AtZeroClock), new LessThan(dv2, dv2));
    assertRewrite(new EqualTo(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2AtZeroClock), new EqualTo(dv2, dv2));
}

