@Test
public void testSetOperation() throws Exception {
    // union
    String sql1 = "explain select * from
" + "  (select k1, k2 from db1.tbl1
" + "   union all
" + "   select k1, k2 from db1.tbl1) a
" + "  inner join
" + "  db1.tbl1 b
" + "  on (a.k1 = b.k1)
" + "where b.k1 = 'a'";
    StmtExecutor stmtExecutor1 = new StmtExecutor(connectContext, sql1);
    stmtExecutor1.execute();
    Planner planner1 = stmtExecutor1.planner();
    String plan1 = planner1.getExplainString(new ExplainOptions(false, false));
    Assertions.assertEquals(1, StringUtils.countMatches(plan1, "UNION"));
    String sql2 = "explain select * from db1.tbl1 where k1='a' and k4=1
" + "union distinct
" + "  (select * from db1.tbl1 where k1='b' and k4=2
" + "   union all
" + "   select * from db1.tbl1 where k1='b' and k4=2)
" + "union distinct
" + "  (select * from db1.tbl1 where k1='b' and k4=2
" + "   union all
" + "   (select * from db1.tbl1 where k1='b' and k4=3)
" + "   order by 3 limit 3)
" + "union all
" + "  (select * from db1.tbl1 where k1='b' and k4=3
" + "   union all
" + "   select * from db1.tbl1 where k1='b' and k4=4)
" + "union all
" + "  (select * from db1.tbl1 where k1='b' and k4=3
" + "   union all
" + "   (select * from db1.tbl1 where k1='b' and k4=5)
" + "   order by 3 limit 3)";
    StmtExecutor stmtExecutor2 = new StmtExecutor(connectContext, sql2);
    stmtExecutor2.execute();
    Planner planner2 = stmtExecutor2.planner();
    String plan2 = planner2.getExplainString(new ExplainOptions(false, false));
    Assertions.assertEquals(4, StringUtils.countMatches(plan2, "UNION"));
    // intersect
    String sql3 = "explain select * from
" + "  (select k1, k2 from db1.tbl1
" + "   intersect
" + "   select k1, k2 from db1.tbl1) a
" + "  inner join
" + "  db1.tbl1 b
" + "  on (a.k1 = b.k1)
" + "where b.k1 = 'a'";
    StmtExecutor stmtExecutor3 = new StmtExecutor(connectContext, sql3);
    stmtExecutor3.execute();
    Planner planner3 = stmtExecutor3.planner();
    String plan3 = planner3.getExplainString(new ExplainOptions(false, false));
    Assertions.assertEquals(1, StringUtils.countMatches(plan3, "INTERSECT"));
    String sql4 = "explain select * from db1.tbl1 where k1='a' and k4=1
" + "intersect distinct
" + "  (select * from db1.tbl1 where k1='b' and k4=2
" + "   intersect
" + "   select * from db1.tbl1 where k1='b' and k4=2)
" + "intersect distinct
" + "  (select * from db1.tbl1 where k1='b' and k4=2
" + "   intersect
" + "   (select * from db1.tbl1 where k1='b' and k4=3)
" + "   order by 3 limit 3)
" + "intersect
" + "  (select * from db1.tbl1 where k1='b' and k4=3
