    String sql55 = "select case when 2 < 1 then 'all' else cast(k1 as int) end as col55, k7 from" + " test.baseall group by col55, k7";
    Assert.assertTrue(StringUtils.containsIgnoreCase(getSQLPlanOrErrorMsg("explain " + sql55), "OUTPUT EXPRS:\n    <slot 2> CAST(`k1` AS INT)\n    <slot 3> `k7`"));
