    Map<PlanFragmentId, Map<Long, Integer>> fragmentIdToBuckendIdBucketCountMap = Deencapsulation.getField(bucketShuffleJoinController, "fragmentIdToBuckendIdBucketCountMap");
    long targetBeCount = fragmentIdToBuckendIdBucketCountMap.values().stream().flatMap(buckend2BucketCountMap -> buckend2BucketCountMap.values().stream()).filter(count -> count == 22).count();
    Assert.assertEquals(targetBeCount, 3);
}

