@Test
public void testQueryDetailQueue() {
    long eventTime = 1592208814796L;
    QueryDetail queryDetail = new QueryDetail(eventTime, "219a2d5443c542d4-8fc938db37c892e3", eventTime, -1, -1, QueryDetail.QueryMemState.RUNNING, "default_cluster:testDb", "select * from table1 limit 1");
    QueryDetailQueue.addOrUpdateQueryDetail(queryDetail);
    List<QueryDetail> queryDetails = QueryDetailQueue.getQueryDetails(eventTime);
    Assert.assertTrue(queryDetails.size() == 0);
    queryDetails = QueryDetailQueue.getQueryDetails(eventTime - 1);
    Assert.assertTrue(queryDetails.size() == 1);
    Gson gson = new Gson();
    String jsonString = gson.toJson(queryDetails);
    String queryDetailString = "[{\"eventTime\":1592208814796," + "\"queryId\":\"219a2d5443c542d4-8fc938db37c892e3\"," + "\"startTime\":1592208814796,\"endTime\":-1,\"latency\":-1," + "\"state\":\"RUNNING\",\"database\":\"testDb\"," + "\"sql\":\"select * from table1 limit 1\"}]";
    Assert.assertEquals(jsonString, queryDetailString);
    queryDetail.setEventTime(eventTime + 1);
    queryDetail.setEndTime(eventTime + 1);
    queryDetail.setLatency(1);
    queryDetail.setState(QueryDetail.QueryMemState.FINISHED);
    QueryDetailQueue.addOrUpdateQueryDetail(queryDetail);
    queryDetails = QueryDetailQueue.getQueryDetails(eventTime);
    Assert.assertTrue(queryDetails.size() == 1);
    jsonString = gson.toJson(queryDetails);
    queryDetailString = "[{\"eventTime\":1592208814797," + "\"queryId\":\"219a2d5443c542d4-8fc938db37c892e3\"," + "\"startTime\":1592208814796,\"endTime\":1592208814797," + "\"latency\":1,\"state\":\"FINISHED\",\"database\":\"testDb\"," + "\"sql\":\"select * from table1 limit 1\"}]";
    Assert.assertEquals(jsonString, queryDetailString);
}

