@Test
public void testRewriteCastString(@Mocked Analyzer analyzer) throws AnalysisException {
    RewriteImplicitCastRule rule = new RewriteImplicitCastRule();
    IntLiteral tinyIntLiteral = new IntLiteral(1);
    SlotId id = new SlotId(0);
    SlotDescriptor slotDesc = new SlotDescriptor(id, null);
    slotDesc.setType(Type.INT);
    SlotRef slotRef = new SlotRef(slotDesc);
    slotRef.setType(Type.INT);
    BinaryPredicate binaryPredicate = new BinaryPredicate(Operator.EQ, slotRef.castTo(Type.BIGINT), tinyIntLiteral);
    rule.apply(binaryPredicate, analyzer, ClauseType.WHERE_CLAUSE);
    Assert.assertTrue(binaryPredicate.getChild(1) instanceof IntLiteral);
    Assert.assertEquals(binaryPredicate.getChild(1).getType(), Type.INT);
    Assert.assertSame(binaryPredicate.getChild(0), slotRef);
    IntLiteral smallIntLiteral = new IntLiteral(IntLiteral.SMALL_INT_MAX);
    slotRef.setType(Type.TINYINT);
    binaryPredicate = new BinaryPredicate(Operator.EQ, slotRef.castTo(Type.BIGINT), smallIntLiteral);
    rule.apply(binaryPredicate, analyzer, ClauseType.WHERE_CLAUSE);
    Assert.assertTrue(binaryPredicate.getChild(0) instanceof CastExpr);
}

